    private boolean activeMerchantWreckInRange() {
        GameObject hook = objects.get("Dragon salvaging hook");
        WorldView sea = client.getTopLevelWorldView();
        if (hook == null || boatView == null || sea == null || sea.getScene() == null) return false;
        net.runelite.api.coords.LocalPoint position = hook.getLocalLocation();
        if (!boatView.isTopLevel()) {
            WorldEntity boat = sea.worldEntities().byIndex(boatView.getId());
            if (boat == null) return false;
            position = boat.transformToMainWorld(position);
        }
        if (position == null) return false;
        int x = position.getSceneX(), y = position.getSceneY(), plane = sea.getPlane();
        Tile[][][] tiles = sea.getScene().getTiles();
        if (plane < 0 || plane >= tiles.length) return false;
        for (int tx = Math.max(0, x - 8); tx <= x + 8 && tx < tiles[plane].length; tx++)
            for (int ty = Math.max(0, y - 8); ty <= y + 8 && ty < tiles[plane][tx].length; ty++) {
                Tile tile = tiles[plane][tx][ty];
                if (tile == null) continue;
                for (GameObject object : tile.getGameObjects()) {
                    if (object == null) continue;
                    ObjectComposition definition = client.getObjectDefinition(object.getId());
                    if (definition.getImpostorIds() != null) definition = definition.getImpostor();
                    if (definition != null
                            && WreckAvailability.reachable(
                                    definition.getId(),
                                    x,
                                    y,
                                    object.getLocalLocation().getSceneX(),
                                    object.getLocalLocation().getSceneY())) return true;
                }
            }
        return false;
    }

    private boolean hasFacilities() {
        return objects.containsKey("Dragon salvaging hook")
                && objects.containsKey("Rosewood cargo hold")
                && objects.containsKey("Salvaging station");
    }

    private static boolean hasObjectAction(ObjectComposition definition, String action) {
        String[] actions = definition.getActions();
        if (actions != null) for (String a : actions) if (action.equals(a)) return true;
        return false;
    }

    private static Map<Integer, Integer> inventoryMap(ItemContainer container) {
        Map<Integer, Integer> result = new HashMap<>();
        if (container != null)
            for (Item item : container.getItems())
                if (item.getId() >= 0 && item.getQuantity() > 0)
                    result.merge(item.getId(), item.getQuantity(), Integer::sum);
        return result;
    }

    private void finishTransfer(ItemContainer inventory) {
        if (transferBefore == null) return;
        if (tick - transferTick > 8) {
            counter.uncertain("Cargo transfer not confirmed; reopen hold");
            transferBefore = null;
            return;
        }
        if (!transferChanged) return;
        Map<Integer, Integer> after = inventoryMap(inventory);
        if (after.equals(transferBefore)) {
            transferChanged = false;
            return;
        }
        // Infer only nonstackable Opulent transfers. An open hold corrects all item types.
        counter.transfer(transferBefore, after, transferDirection, transferSawSnapshot);
        transferBefore = null;
        transferChanged = false;
    }

    private GuideEngine.Kind bagKind(int id) {
        if (id == 33395 || id == 33393) return GuideEngine.Kind.GEM;
        if (id == 33137 || id == 33135) return GuideEngine.Kind.HERB;
        if (id == 24482 || id == 13639) return GuideEngine.Kind.SEED;
        return GuideEngine.Kind.OTHER;
    }

    @Subscribe(priority = -1000)
    public void onPostMenuSort(PostMenuSort e) {
        if (!config.menuSwap()
                || client.getGameState() != GameState.LOGGED_IN
                || client.isMenuOpen()
                || client.isWidgetSelected()) return;
        MenuEntry[] entries = client.getMenu().getMenuEntries();
        if (entries.length == 0) return;
        int wreckWalk = ShipwreckMenuSwap.select(entries);
        if (wreckWalk >= 0) {
            BoatMenuGuard.promote(entries, wreckWalk);
            client.getMenu().setMenuEntries(entries);
            return;
        }
        Player player = client.getLocalPlayer();
        if (!view.onBoat
                || !hasFacilities()
                || client.getGameState() != GameState.LOGGED_IN
                || player == null
                || player.getWorldView() != boatView
                || client.isMenuOpen()
                || client.isWidgetSelected()) return;
        if (decision.action == GuideEngine.Action.SELECT_STORE_ITEM
                || decision.action == GuideEngine.Action.SELECT_SEED) {
            ItemContainer inventory = client.getItemContainer(93);
            int slot = decision.slot;
            if (inventory != null && slot >= 0 && slot < inventory.getItems().length) {
                Item item = inventory.getItems()[slot];
                if (item.getId() >= 0 && item.getQuantity() > 0) {
                    ItemComposition def = itemManager.getItemComposition(item.getId());
                    GuideEngine.Kind kind = LootPolicy.kind(def.getName(), config);
                    boolean allowed =
                            decision.action == GuideEngine.Action.SELECT_SEED
                                    ? kind == GuideEngine.Kind.SELECTED_SEED
                                    : kind == GuideEngine.Kind.GEM || kind == GuideEngine.Kind.HERB;
                    int index =
                            allowed && def.getNote() == -1
                                    ? DropMenuSwap.selectUse(entries, slot, item.getId())
                                    : -1;
                    if (index >= 0) {
                        DropMenuSwap.promote(entries, index);
                        client.getMenu().setMenuEntries(entries);
                        return;
                    }
                }
            }
        }
        GuideEngine.Kind checkBag =
                decision.action == GuideEngine.Action.CHECK_GEMS
                        ? GuideEngine.Kind.GEM
                        : decision.action == GuideEngine.Action.CHECK_HERBS
                                ? GuideEngine.Kind.HERB
                                : decision.action == GuideEngine.Action.CHECK_SEEDS
                                        ? GuideEngine.Kind.SEED
                                        : GuideEngine.Kind.OTHER;
        if (checkBag != GuideEngine.Kind.OTHER) {
            MenuEntry hovered = entries[entries.length - 1];
            int slot = hovered.getParam0();
            ItemContainer inventory = client.getItemContainer(93);
            if (hovered.getParam1() == DropMenuSwap.INVENTORY_WIDGET
                    && inventory != null
                    && slot >= 0
                    && slot < inventory.getItems().length) {
                Item item = inventory.getItems()[slot];
                int index =
                        DropMenuSwap.selectOption(
                                entries,
                                slot,
                                item.getId(),
                                item.getQuantity() > 0 && bagKind(item.getId()) == checkBag,
                                "Check");
                if (index >= 0) {
                    DropMenuSwap.promote(entries, index);
                    client.getMenu().setMenuEntries(entries);
                    return;
                }
            }
        }
        if (decision.action == GuideEngine.Action.DROP_ITEM) {
            MenuEntry hovered = entries[entries.length - 1];
            int slot = hovered.getParam0();
            ItemContainer inventory = client.getItemContainer(93);
            if (hovered.getParam1() == DropMenuSwap.INVENTORY_WIDGET
                    && inventory != null
                    && slot >= 0
                    && slot < inventory.getItems().length) {
                Item item = inventory.getItems()[slot];
                if (item.getId() >= 0 && item.getQuantity() > 0) {
                    String name = itemManager.getItemComposition(item.getId()).getName();
                    GuideEngine.Kind kind =
                            itemManager.getItemComposition(item.getId()).getNote() != -1
                                    ? GuideEngine.Kind.OTHER
                                    : LootPolicy.kind(name, config);
                    int index =
                            DropMenuSwap.select(
                                    entries, slot, item.getId(), dropAllowed(kind, name));
                    if (index >= 0) {
                        DropMenuSwap.promote(entries, index);
                        client.getMenu().setMenuEntries(entries);
                        return;
                    }
                }
            }
        }
        int index = BoatMenuGuard.select(entries, boatView.getId(), currentWorldAction(entries));
        if (index >= 0) {
            BoatMenuGuard.promote(entries, index);
            client.getMenu().setMenuEntries(entries);
        }
    }

    private int currentWorldAction(MenuEntry[] entries) {
        String name, option;
        switch (decision.action) {
            case DEPLOY:
                name = "Dragon salvaging hook";
                option = "Deploy";
                break;
            case DEPOSIT:
                name = "Rosewood cargo hold";
                option = "Deposit-all";
                break;
            case OPEN_CARGO:
                name = "Rosewood cargo hold";
                option = "Open";
                break;
            case SORT:
                name = "Salvaging station";
                option = "Sort-salvage";
                break;
            case ACTIVATE_EXTRACTOR:
                name = "Crystal extractor";
                option = "Activate";
                break;
            case HARVEST_EXTRACTOR:
                name = "Crystal extractor";
                option = "Harvest";
                break;
            default:
                return -1;
        }
        GameObject object = objects.get(name);
        if (object == null) return -1;
        ObjectComposition definition = client.getObjectDefinition(object.getId());
        if (definition.getImpostorIds() != null) definition = definition.getImpostor();
        Point min = object.getSceneMinLocation(), max = object.getSceneMaxLocation();
        for (int i = entries.length - 1; i >= 0; i--) {
            MenuEntry entry = entries[i];
            if (BoatMenuGuard.objectAction(entry.getType())
                    && entry.getWorldViewId() == boatView.getId()
                    && clean(entry.getTarget()).equals(name)
                    && entry.getOption().equals(option)
                    && (entry.getIdentifier() == object.getId()
                            || (definition != null && entry.getIdentifier() == definition.getId()))
                    && entry.getParam0() >= min.getX()
                    && entry.getParam0() <= max.getX()
                    && entry.getParam1() >= min.getY()
                    && entry.getParam1() <= max.getY()) return i;
        }
        return -1;
    }

    Shape shape(GuideEngine.Action action, int slot) {
        Widget w = null;
        switch (action) {
            case DEPLOY:
                return objectShape("Dragon salvaging hook");
            case DEPOSIT:
            case OPEN_CARGO:
                return objectShape("Rosewood cargo hold");
            case SORT:
                return objectShape("Salvaging station");
            case ACTIVATE_EXTRACTOR:
            case HARVEST_EXTRACTOR:
                return objectShape("Crystal extractor");
            case CLOSE_SEED_BOX:
                w = client.getWidget(128, 2);
                break;
            case CLOSE_CARGO:
                w = child(61800449, 11);
                break;
            case WITHDRAW:
                for (Widget q : widgets)
                    if (q.getId() == 61800458
                            && q.getItemId() == 32861
                            && hasAction(q, "Withdraw-All")) {
                        w = q;
                        break;
                    }
                break;
            case SAILING_TAB:
                w = actionWidget("Sailing Options");
                break;
            case INVENTORY_TAB:
                w = actionWidget("Inventory");
                break;
            case MAGIC_TAB:
                w = actionWidget("Magic");
                break;
            case FACILITIES_TAB:
                w = client.getWidget(937, 33);
                break;
            case ASSIGN_HOOK:
                w = child(61407257, 47);
                if (!hasAction(w, "Assign")) w = null;
                break;
            case JENKINS:
                Widget label = child(61407253, 14);
                if (label != null && clean(label.getText()).contains("Cabin Boy Jenkins"))
                    w = child(61407252, 3);
                break;
            case HIGH_ALCH:
                w = client.getWidget(14286895);
                break;
            case SELECT_STORE_ITEM:
            case SELECT_SEED:
            case ALCH_ITEM:
            case DROP_ITEM:
                return inventoryShape(slot);
            case USE_GEM_BAG:
            case CHECK_GEMS:
            case FILL_GEMS:
                return bagShape(GuideEngine.Kind.GEM);
            case USE_HERB_BAG:
            case CHECK_HERBS:
            case FILL_HERBS:
                return bagShape(GuideEngine.Kind.HERB);
            case USE_SEED_BOX:
            case CHECK_SEEDS:
            case FILL_SEEDS:
                return bagShape(GuideEngine.Kind.SEED);
            default:
                return null;
        }
        return visible(w) ? w.getBounds() : null;
    }

    private Shape objectShape(String name) {
        GameObject o = objects.get(name);
        if (o == null) return null;
        return o.getClickbox();
    }

    private Shape bagShape(GuideEngine.Kind kind) {
        for (GuideEngine.Entry i : view.inventory)
            if (bagKind(i.id) == kind) return inventoryShape(i.slot);
        return null;
    }

    List<Shape> dropShapes() {
        List<Shape> result = new ArrayList<>();
        if (decision.action != GuideEngine.Action.DROP_ITEM) return result;
        ItemContainer inventory = client.getItemContainer(93);
        if (inventory == null) return result;
        Item[] items = inventory.getItems();
        for (int slot = 0; slot < items.length; slot++) {
            Item item = items[slot];
            if (item.getId() < 0 || item.getQuantity() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            GuideEngine.Kind kind =
                    itemManager.getItemComposition(item.getId()).getNote() != -1
                            ? GuideEngine.Kind.OTHER
                            : LootPolicy.kind(name, config);
            if (dropAllowed(kind, name)) {
                Shape shape = inventoryShape(slot);
                if (shape != null) result.add(shape);
            }
        }
        return result;
    }

    private boolean dropAllowed(GuideEngine.Kind kind, String name) {
        GuideEngine.View live = new GuideEngine.View();
        live.dropOverflow = config.dropOverflow();
        ItemContainer inventory = client.getItemContainer(93);
        if (inventory != null)
            for (Item i : inventory.getItems())
                if (i.getQuantity() > 0) {
                    GuideEngine.Kind bag = bagKind(i.getId());
                    if (bag == GuideEngine.Kind.GEM) live.gemsPresent = true;
                    if (bag == GuideEngine.Kind.HERB) live.herbsPresent = true;
                    if (bag == GuideEngine.Kind.SEED) live.seedsPresent = true;
                }
        return LootPolicy.drop(
                new GuideEngine.Entry(-1, -1, 1, name, kind, bags.fit(kind, name)), live);
    }

    private Shape inventoryShape(int slot) {
        Widget inv = client.getWidget(149, 0);
        if (!visible(inv) || slot < 0) return null;
        Widget item = inv.getChild(slot);
        return visible(item) ? item.getBounds() : null;
    }

    private Widget actionWidget(String option) {
        for (Widget w : widgets) if (hasAction(w, option) && (w.getId() >>> 16) != 937) return w;
        return null;
    }

    private static boolean hasAction(Widget w, String action) {
        if (w == null || w.getActions() == null) return false;
        for (String s : w.getActions()) if (action.equals(s)) return true;
        return false;
    }

    private Widget child(int id, int index) {
        Widget p = client.getWidget(id);
        return p == null ? null : p.getChild(index);
    }

    private static boolean visible(Widget w) {
        return w != null && !w.isHidden();
    }

    private static String clean(String s) {
        return s == null ? "" : s.replaceAll("<br\\s*/?>", " ").replaceAll("<[^>]*>", "");
    }
}

package com.lazysalvaging;

import java.util.ArrayList;
import java.util.List;

/** Pure decision logic. No client calls, menu mutation, or input execution. */
final class GuideEngine {
    enum Mode {
        UNKNOWN,
        ACTIVE,
        SORTING
    }

    enum Stage {
        PREPARE,
        ASSIGN,
        PROCESS,
        BEFORE_CLEANUP,
        CLEANUP,
        RECHECK
    }

    enum Kind {
        OTHER,
        ALCHEMY,
        DROP,
        GEM,
        HERB,
        SEED,
        SELECTED_SEED
    }

    enum Fit {
        UNKNOWN,
        YES,
        NO
    }

    enum Action {
        NONE,
        OPEN_CARGO,
        CLOSE_CARGO,
        CLOSE_SEED_BOX,
        WITHDRAW,
        DEPLOY,
        DEPOSIT,
        SORT,
        ACTIVATE_EXTRACTOR,
        HARVEST_EXTRACTOR,
        SAILING_TAB,
        FACILITIES_TAB,
        ASSIGN_HOOK,
        JENKINS,
        INVENTORY_TAB,
        MAGIC_TAB,
        HIGH_ALCH,
        ALCH_ITEM,
        SELECT_SEED,
        USE_SEED_BOX,
        SELECT_STORE_ITEM,
        USE_GEM_BAG,
        USE_HERB_BAG,
        DROP_ITEM,
        CHECK_GEMS,
        CHECK_HERBS,
        CHECK_SEEDS,
        FILL_GEMS,
        FILL_HERBS,
        FILL_SEEDS
    }

    static final class Entry {
        final int slot, id, quantity;
        final String name;
        final Kind kind;
        final Fit fit;

        Entry(int slot, int id, int quantity, String name, Kind kind, Fit fit) {
            this.slot = slot;
            this.id = id;
            this.quantity = quantity;
            this.name = name;
            this.kind = kind;
            this.fit = fit;
        }
    }

    static final class View {
        boolean seedBoxOpen, seedBoxKnown, wreckAvailable;
        boolean onBoat,
                cargoOpen,
                cargoFresh,
                cargoKnown,
                inventoryVisible,
                magicVisible,
                sailingVisible,
                facilitiesVisible,
                assignmentPicker,
                crewAssigned,
                salvaging,
                sorting,
                depleted,
                alchSelected,
                alchReturning,
                gemsPresent,
                herbsPresent,
                seedsPresent;
        int selectedSeedSlot = -1, selectedStoreSlot = -1;
        boolean dropOverflow;
        boolean seedSelectionInvalid, seedDepositBlocked;
        int cargoSlots = -1, cargoSalvage = -1, salvage, occupied;
        boolean trackExtractor, extractorInactive, extractorReady, extractorBusy;
        String alchBlocked = "";
        List<Entry> inventory = new ArrayList<>();
    }

    static final class Decision {
        final Action action, preview;
        final int slot;
        final String text;

        Decision(Action action, Action preview, int slot, String text) {
            this.action = action;
            this.preview = preview;
            this.slot = slot;
            this.text = text;
        }

        @Override
        public String toString() {
            return action + ":" + slot + ":" + text;
        }
    }

    Mode mode = Mode.UNKNOWN;
    Stage stage = Stage.PREPARE;
    boolean cargoRequired = true, assignRequired = true;

    void reset() {
        mode = Mode.UNKNOWN;
        stage = Stage.PREPARE;
        cargoRequired = true;
        assignRequired = true;
    }

    void deposited() {
        if (mode == Mode.ACTIVE) cargoRequired = true;
    }

    private Decision d(Action a, Action p, String text) {
        return new Decision(a, p, -1, text);
    }

    private Decision item(Action a, Entry i, String text) {
        return new Decision(a, Action.NONE, i.slot, text + " " + i.name);
    }

    Decision decide(View v) {
        return withExtractorPreview(v, decideCurrent(v));
    }

    Decision withExtractorPreview(View v, Decision current) {
        if (mode != Mode.ACTIVE)
            return current.preview == Action.ACTIVATE_EXTRACTOR
                            || current.preview == Action.HARVEST_EXTRACTOR
                    ? new Decision(current.action, Action.NONE, current.slot, current.text)
                    : current;
        if (!v.onBoat
                || !v.trackExtractor
                || v.extractorBusy
                || current.action == Action.ACTIVATE_EXTRACTOR
                || current.action == Action.HARVEST_EXTRACTOR) return current;
        Action due =
                v.extractorInactive
                        ? Action.ACTIVATE_EXTRACTOR
                        : v.extractorReady ? Action.HARVEST_EXTRACTOR : Action.NONE;
        return due == Action.NONE
                ? current
                : new Decision(current.action, due, current.slot, current.text);
    }

    private Decision decideCurrent(View v) {
        if (!v.onBoat)
            return d(
                    Action.NONE,
                    Action.NONE,
                    "Board your boat with the configured salvaging facilities");
        if (v.seedBoxOpen)
            return v.seedBoxKnown
                    ? d(Action.CLOSE_SEED_BOX, Action.NONE, "Close seed box to continue cleanup")
                    : d(Action.NONE, Action.NONE, "Waiting for seed box contents");
        for (int pass = 0; pass < 12; pass++) {
            if (mode == Mode.UNKNOWN || mode == Mode.ACTIVE) {
                cargoRequired = !(v.cargoKnown || v.cargoFresh);
                if (cargoRequired && !v.cargoOpen)
                    return d(
                            Action.OPEN_CARGO,
                            Action.NONE,
                            "Open cargo hold to initialize or refresh the counter");
                if (cargoRequired)
                    return d(Action.NONE, Action.NONE, "Waiting for current cargo contents");
                cargoRequired = false;
                if ((v.cargoSlots >= 210 || (v.occupied >= 28 && depositReachesSortingThreshold(v)))
                        && (mode == Mode.UNKNOWN || !v.salvaging || v.occupied >= 28)) {
                    mode = Mode.SORTING;
                    stage = Stage.PREPARE;
                    assignRequired = true;
                } else mode = Mode.ACTIVE;
            }
            if (mode == Mode.ACTIVE) {
                if (v.cargoOpen)
                    return d(
                            Action.CLOSE_CARGO,
                            v.wreckAvailable ? Action.DEPLOY : Action.NONE,
                            "Close cargo hold");
                if (v.occupied >= 28) {
                    Decision priority = extractor(v);
                    if (priority != null) return priority;
                    if (v.salvage == 0)
                        return d(
                                Action.NONE,
                                Action.NONE,
                                "Inventory full without salvage; make room to continue");
                    return d(Action.DEPOSIT, Action.NONE, "Deposit-all salvage into cargo hold");
                }
                if (!v.wreckAvailable) {
                    Decision priority = extractor(v);
                    if (priority != null) return priority;
                    return d(
                            Action.NONE,
                            Action.NONE,
                            "Waiting for an active Merchant shipwreck in range");
                }
                if (v.salvaging && !v.depleted)
                    return d(
                            Action.NONE,
                            depositReachesSortingThreshold(v) ? Action.SAILING_TAB : Action.DEPOSIT,
                            "Salvaging — wait for a full inventory");
                Decision priority = extractor(v);
                if (priority != null) return priority;
                if (v.depleted)
                    return d(
                            Action.DEPLOY,
                            Action.DEPOSIT,
                            "Wreck depleted: deploy the hook at the next wreck");
                return d(Action.DEPLOY, Action.DEPOSIT, "Deploy Dragon salvaging hook");
            }
            if (stage == Stage.PREPARE) {
                if (!v.cargoOpen) {
                    Decision priority = extractor(v);
                    if (priority != null) return priority;
                }
                if (v.occupied < 28) {
                    if (!v.cargoOpen)
                        return d(
                                Action.OPEN_CARGO,
                                Action.NONE,
                                "Open cargo hold to fill inventory with salvage");
                    if (!v.cargoFresh)
                        return d(Action.NONE, Action.NONE, "Waiting for current cargo contents");
                    if (v.cargoSalvage > 0)
                        return d(Action.WITHDRAW, Action.NONE, "Withdraw-All Opulent salvage");
                }
                stage = assignRequired ? Stage.ASSIGN : Stage.PROCESS;
                continue;
            }
            if (v.cargoOpen && stage != Stage.RECHECK)
                return d(Action.CLOSE_CARGO, Action.NONE, "Close cargo hold");
            if (stage == Stage.ASSIGN) {
                if (v.crewAssigned) {
                    assignRequired = false;
                    stage = Stage.PROCESS;
                    continue;
                }
                if (v.assignmentPicker)
                    return d(Action.JENKINS, Action.NONE, "Assign Cabin Boy Jenkins to the hook");
                if (!v.sailingVisible)
                    return d(Action.SAILING_TAB, Action.NONE, "Open Sailing Options");
                if (!v.facilitiesVisible)
                    return d(Action.FACILITIES_TAB, Action.NONE, "Open Facilities");
                return d(Action.ASSIGN_HOOK, Action.NONE, "Assign crew to Dragon salvaging hook");
            }
            if (stage == Stage.PROCESS) {
                if (v.salvage == 0) {
                    stage = Stage.BEFORE_CLEANUP;
                    continue;
                }
                if (v.sorting) {
                    if (!v.inventoryVisible)
                        return d(
                                Action.INVENTORY_TAB,
                                Action.NONE,
                                "Open Inventory while sorting continues");
                    Action preview = Action.NONE;
                    for (Entry i : v.inventory)
                        if (i.kind == Kind.GEM) {
                            preview = Action.CHECK_GEMS;
                            break;
                        }
                    return d(Action.NONE, preview, "Sorting salvage — wait for completion");
                }
                Decision priority = extractor(v);
                if (priority != null) return priority;
                return d(Action.SORT, Action.NONE, "Sort-salvage at the Salvaging station");
            }
            if (stage == Stage.BEFORE_CLEANUP) {
                Decision priority = extractor(v);
                if (priority != null) return priority;
                stage = Stage.CLEANUP;
                continue;
            }
            if (stage == Stage.CLEANUP) {
                Decision next = cleanup(v);
                if (next != null) return next;
                stage = Stage.RECHECK;
                continue;
            }
            if (stage == Stage.RECHECK) {
                Decision priority = extractor(v);
                if (priority != null) return priority;
                if (!(v.cargoKnown || v.cargoFresh) && !v.cargoOpen)
                    return d(
                            Action.OPEN_CARGO,
                            Action.NONE,
                            "Open cargo hold to refresh the counter");
                if (!(v.cargoKnown || v.cargoFresh))
                    return d(Action.NONE, Action.NONE, "Waiting for current cargo contents");
                if (v.cargoSlots >= 15) {
                    stage = Stage.PREPARE;
                    continue;
                }
                mode = Mode.ACTIVE;
                cargoRequired = false;
                continue;
            }
        }
        return d(Action.NONE, Action.NONE, "Waiting for inventory space or a fresh observation");
    }

    private boolean depositReachesSortingThreshold(View v) {
        return v.salvage > 0 && v.cargoSlots >= 0 && (long) v.cargoSlots + v.salvage >= 210;
    }

    private Decision extractor(View v) {
        if (!v.trackExtractor) return null;
        if (v.extractorBusy)
            return d(Action.NONE, Action.NONE, "Crystal extractor — wait for completion");
        Action action =
                v.extractorInactive
                        ? Action.ACTIVATE_EXTRACTOR
                        : v.extractorReady ? Action.HARVEST_EXTRACTOR : Action.NONE;
        if (action == Action.NONE) return null;
        if (v.cargoOpen)
            return d(Action.CLOSE_CARGO, action, "Close cargo hold to tend the crystal extractor");
        return d(
                action,
                Action.NONE,
                action == Action.ACTIVATE_EXTRACTOR
                        ? "Activate Crystal extractor"
                        : "Harvest Crystal extractor");
    }

    private Decision bag(
            View v, Kind kind, boolean present, Action check, Action fill, String label) {
        Entry unknown = null, fitting = null;
        for (Entry i : v.inventory)
            if (i.kind == kind) {
                if (i.fit == Fit.UNKNOWN && unknown == null) unknown = i;
                if (i.fit == Fit.YES && fitting == null) fitting = i;
            }
        if (unknown == null && fitting == null) return null;
        if (!present) return null; // Keep stored items when their container is missing.
        if (!v.inventoryVisible) return d(Action.INVENTORY_TAB, Action.NONE, "Open Inventory");
        if (unknown != null)
            return d(check, Action.NONE, "Check " + label + " to read its contents");
        for (Entry i : v.inventory)
            if (i.kind != kind
                    && BagFillTracker.accepts(kind, i.name.toLowerCase(java.util.Locale.ROOT))) {
                Action use = kind == Kind.GEM ? Action.USE_GEM_BAG : Action.USE_HERB_BAG;
                if (v.selectedStoreSlot == fitting.slot)
                    return new Decision(
                            use, Action.NONE, fitting.slot, "Use " + fitting.name + " on " + label);
                return new Decision(
                        Action.SELECT_STORE_ITEM, use, fitting.slot, "Use " + fitting.name);
            }
        return d(fill, Action.NONE, "Fill " + label);
    }

    private Decision cleanup(View v) {
        if (v.alchReturning)
            return d(
                    Action.NONE,
                    Action.NONE,
                    "Waiting for High Level Alchemy to return to the spellbook");
        if (v.seedSelectionInvalid)
            return d(Action.NONE, Action.NONE, "Choose at most 6 seeds in Seed Box settings");
        Decision result =
                bag(v, Kind.GEM, v.gemsPresent, Action.CHECK_GEMS, Action.FILL_GEMS, "gem sack");
        if (result != null) return result;
        result =
                bag(
                        v,
                        Kind.HERB,
                        v.herbsPresent,
                        Action.CHECK_HERBS,
                        Action.FILL_HERBS,
                        "silklined herb sack");
        if (result != null) return result;
        for (Entry i : v.inventory)
            if (i.kind == Kind.ALCHEMY) {
                if (!v.alchBlocked.isEmpty())
                    return d(Action.NONE, Action.NONE, "Alchemy paused: " + v.alchBlocked);
                if (v.alchSelected) return item(Action.ALCH_ITEM, i, "High Level Alchemy:");
                if (!v.magicVisible)
                    return d(Action.MAGIC_TAB, Action.NONE, "Open Magic for High Level Alchemy");
                return d(Action.HIGH_ALCH, Action.NONE, "Select High Level Alchemy");
            }
        // Return to Inventory even if cleanup has no remaining item actions.
        if (v.magicVisible || v.alchSelected)
            return d(
                    Action.INVENTORY_TAB,
                    Action.NONE,
                    "Return to Inventory; cancel selected spell if necessary");
        for (Entry i : v.inventory)
            if (LootPolicy.drop(i, v)) {
                if (!v.inventoryVisible)
                    return d(Action.INVENTORY_TAB, Action.NONE, "Open Inventory");
                return item(Action.DROP_ITEM, i, "Drop:");
            }
        for (Entry i : v.inventory)
            if (i.kind == Kind.SELECTED_SEED) {
                if (!v.seedsPresent || i.fit == Fit.NO) continue;
                if (!v.inventoryVisible)
                    return d(Action.INVENTORY_TAB, Action.NONE, "Open Inventory");
                if (v.seedDepositBlocked) {
                    if (i.fit == Fit.UNKNOWN)
                        return d(
                                Action.CHECK_SEEDS,
                                Action.NONE,
                                "Check seed box to confirm space after the unconfirmed deposit");
                    return d(
                            Action.NONE,
                            Action.NONE,
                            "Seed deposit not confirmed: make room in the box, then reset guide");
                }
                if (v.selectedSeedSlot == i.slot)
                    return new Decision(
                            Action.USE_SEED_BOX,
                            Action.NONE,
                            i.slot,
                            "Use " + i.name + " on seed box");
                return new Decision(
                        Action.SELECT_SEED, Action.USE_SEED_BOX, i.slot, "Use " + i.name);
            }
        return null;
    }

    static boolean isBag(Kind kind) {
        return kind == Kind.GEM || kind == Kind.HERB || kind == Kind.SEED;
    }
}

package com.lazysalvaging;

import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;

import java.awt.*;

import javax.inject.Inject;

final class GuideHud extends OverlayPanel {
    private final GuideController guide;
    private final LazySalvagingConfig config;

    @Inject
    GuideHud(GuideController guide, LazySalvagingConfig config) {
        this.guide = guide;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(210, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.hud()) return null;
        panelComponent.getChildren().clear();
        panelComponent.setBackgroundColor(
                new Color(30, 30, 30, Math.max(0, Math.min(100, config.hudOpacity())) * 255 / 100));
        boolean active = guide.engine.mode == GuideEngine.Mode.ACTIVE;
        boolean sorting = guide.engine.mode == GuideEngine.Mode.SORTING;
        panelComponent
                .getChildren()
                .add(
                        LineComponent.builder()
                                .left("[ Salvaging ]")
                                .right("[ Sorting ]")
                                .leftColor(active ? config.current() : Color.GRAY)
                                .rightColor(sorting ? config.current() : Color.GRAY)
                                .build());
        panelComponent
                .getChildren()
                .add(
                        LineComponent.builder()
                                .left("Cargo hold:")
                                .right(
                                        (guide.counter.known()
                                                        ? Integer.toString(guide.counter.slots())
                                                        : "?")
                                                + " / 240")
                                .build());
        panelComponent
                .getChildren()
                .add(
                        LineComponent.builder()
                                .left("Total sorted:")
                                .right(Long.toString(guide.totals.sorted()))
                                .build());
        if (config.trackExtractor())
            panelComponent
                    .getChildren()
                    .add(
                            LineComponent.builder()
                                    .left("Crystal harvests:")
                                    .right(Long.toString(guide.totals.harvests()))
                                    .build());
        return super.render(graphics);
    }
}

package com.lazysalvaging;

import net.runelite.client.ui.overlay.*;

import java.awt.*;

import javax.inject.Inject;

final class GuideOverlay extends Overlay {
    private final GuideController guide;
    private final LazySalvagingConfig config;

    @Inject
    GuideOverlay(GuideController guide, LazySalvagingConfig config) {
        this.guide = guide;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g) {
        GuideEngine.Decision d = guide.decision;
        Shape current = guide.shape(d.action, d.slot);
        Shape next = config.preview() ? guide.shape(d.preview, -1) : null;
        if (next != null && (current == null || !next.getBounds().equals(current.getBounds())))
            draw(g, next, config.next());
        if (d.action == GuideEngine.Action.DROP_ITEM) {
            for (Shape shape : guide.dropShapes()) draw(g, shape, config.drop());
            return null;
        }
        Color color;
        switch (d.action) {
            case INVENTORY_TAB:
                color = config.inventoryTabColor();
                break;
            case MAGIC_TAB:
                color = config.magicTabColor();
                break;
            case SAILING_TAB:
                color = config.sailingTabColor();
                break;
            case CLOSE_CARGO:
                color = config.cargoCloseColor();
                break;
            case ALCH_ITEM:
                color = config.alchemy();
                break;
            default:
                color = config.current();
                break;
        }
        if (current != null) draw(g, current, color);
        return null;
    }

    private void draw(Graphics2D g, Shape shape, Color color) {
        Color old = g.getColor();
        Stroke stroke = g.getStroke();
        g.setColor(
                new Color(
                        color.getRed(),
                        color.getGreen(),
                        color.getBlue(),
                        config.fill() * 255 / 100));
        g.fill(shape);
        g.setStroke(new BasicStroke(2));
        g.setColor(color);
        g.draw(shape);
        g.setStroke(stroke);
        g.setColor(old);
    }
}

