            case "uncut jade":
                return classify(c.lootUncutJade().name(), GuideEngine.Kind.GEM);
            case "uncut red topaz":
                return classify(c.lootUncutRedTopaz().name(), GuideEngine.Kind.GEM);
            case "uncut sapphire":
                return classify(c.lootUncutSapphire().name(), GuideEngine.Kind.GEM);
            case "uncut emerald":
                return classify(c.lootUncutEmerald().name(), GuideEngine.Kind.GEM);
            case "uncut ruby":
                return classify(c.lootUncutRuby().name(), GuideEngine.Kind.GEM);
            case "uncut diamond":
                return classify(c.lootUncutDiamond().name(), GuideEngine.Kind.GEM);
            default:
                return GuideEngine.Kind.OTHER;
        }
    }

    private static GuideEngine.Kind classify(String action, GuideEngine.Kind stored) {
        switch (action) {
            case "DROP":
                return GuideEngine.Kind.DROP;
            case "ALCH":
                return GuideEngine.Kind.ALCHEMY;
            case "STORE":
                return stored;
            default:
                return GuideEngine.Kind.OTHER;
        }
    }

    static boolean drop(GuideEngine.Entry item, GuideEngine.View v) {
        if (item.kind == GuideEngine.Kind.DROP) return true;
        if (!v.dropOverflow || item.fit != GuideEngine.Fit.NO) return false;
        return item.kind == GuideEngine.Kind.GEM && v.gemsPresent
                || item.kind == GuideEngine.Kind.HERB && v.herbsPresent
                || item.kind == GuideEngine.Kind.SELECTED_SEED && v.seedsPresent;
    }
}

package com.lazysalvaging;

import java.util.*;

/** Seed types on the Opulent salvage drop table. */
public enum SalvageSeed {
    AVANTOE("Avantoe seed"),
    BELLADONNA("Belladonna seed"),
    CACTUS("Cactus seed"),
    CADANTINE("Cadantine seed"),
    DWARF_WEED("Dwarf weed seed"),
    IRIT("Irit seed"),
    KWUARM("Kwuarm seed"),
    LANTADYME("Lantadyme seed"),
    POISON_IVY("Poison ivy seed"),
    POTATO_CACTUS("Potato cactus seed"),
    SNAPDRAGON("Snapdragon seed"),
    SNAPE_GRASS("Snape grass seed"),
    TOADFLAX("Toadflax seed"),
    TORSTOL("Torstol seed");
    public final String itemName;

    SalvageSeed(String name) {
        itemName = name;
    }

    @Override
    public String toString() {
        return itemName;
    }

    static GuideEngine.Kind classify(String name, Set<SalvageSeed> selected) {
        for (SalvageSeed seed : values())
            if (seed.itemName.equalsIgnoreCase(name))
                return selected.contains(seed)
                        ? GuideEngine.Kind.SELECTED_SEED
                        : ItemRules.kind(name) == GuideEngine.Kind.DROP
                                ? GuideEngine.Kind.DROP
                                : GuideEngine.Kind.OTHER;
        return ItemRules.kind(name);
    }
}

package com.lazysalvaging;

/** Tolerate one idle animation tick, but never latch activity on an operating varbit. */
final class SalvagingActivity {
    private int idleTicks = 2;

    void reset() {
        idleTicks = 2;
    }

    boolean observe(int animation) {
        if (animation == 13583 || animation == 13584) idleTicks = 0;
        else idleTicks = Math.min(2, idleTicks + 1);
        return idleTicks < 2;
    }
}

package com.lazysalvaging;

import net.runelite.client.config.ConfigManager;

import java.util.*;

final class SeedSettings {
    static String key(SalvageSeed seed) {
        switch (seed) {
            case AVANTOE:
                return "seedAvantoe";
            case BELLADONNA:
                return "seedBelladonna";
            case CACTUS:
                return "seedCactus";
            case CADANTINE:
                return "seedCadantine";
            case DWARF_WEED:
                return "seedDwarfWeed";
            case IRIT:
                return "seedIrit";
            case KWUARM:
                return "seedKwuarm";
            case LANTADYME:
                return "seedLantadyme";
            case POISON_IVY:
                return "seedPoisonIvy";
            case POTATO_CACTUS:
                return "seedPotatoCactus";
            case SNAPDRAGON:
                return "seedSnapdragon";
            case SNAPE_GRASS:
                return "seedSnapeGrass";
            case TOADFLAX:
                return "seedToadflax";
            case TORSTOL:
                return "seedTorstol";
            default:
                throw new IllegalArgumentException("Unknown seed");
        }
    }

    static Set<SalvageSeed> selected(LazySalvagingConfig config) {
        Set<SalvageSeed> result = EnumSet.noneOf(SalvageSeed.class);
        if (config.seedAvantoe()) result.add(SalvageSeed.AVANTOE);
        if (config.seedBelladonna()) result.add(SalvageSeed.BELLADONNA);
        if (config.seedCactus()) result.add(SalvageSeed.CACTUS);
        if (config.seedCadantine()) result.add(SalvageSeed.CADANTINE);
        if (config.seedDwarfWeed()) result.add(SalvageSeed.DWARF_WEED);
        if (config.seedIrit()) result.add(SalvageSeed.IRIT);
        if (config.seedKwuarm()) result.add(SalvageSeed.KWUARM);
        if (config.seedLantadyme()) result.add(SalvageSeed.LANTADYME);
        if (config.seedPoisonIvy()) result.add(SalvageSeed.POISON_IVY);
        if (config.seedPotatoCactus()) result.add(SalvageSeed.POTATO_CACTUS);
        if (config.seedSnapdragon()) result.add(SalvageSeed.SNAPDRAGON);
        if (config.seedSnapeGrass()) result.add(SalvageSeed.SNAPE_GRASS);
        if (config.seedToadflax()) result.add(SalvageSeed.TOADFLAX);
        if (config.seedTorstol()) result.add(SalvageSeed.TORSTOL);
        return result;
    }

    static void save(ConfigManager manager, Set<SalvageSeed> selected) {
        // Remove first, so replacing a type never briefly creates seven selections.
        for (SalvageSeed seed : SalvageSeed.values())
            if (!selected.contains(seed))
                manager.setConfiguration("lazysalvaging", key(seed), false);
        for (SalvageSeed seed : selected)
            manager.setConfiguration("lazysalvaging", key(seed), true);
    }
}

package com.lazysalvaging;

/** Confirmed Sailing rewards, never menu clicks. Totals survive a cargo-guide reset. */
final class SessionTotals {
    private int lastXp = -1;
    private long sorted, harvests;

    long sorted() {
        return sorted;
    }

    long harvests() {
        return harvests;
    }

    void baseline(int xp) {
        lastXp = xp;
    }

    void baselineIfMissing(int xp) {
        if (lastXp < 0) baseline(xp);
    }

    void reset(int xp) {
        sorted = harvests = 0;
        baseline(xp);
    }

    void xp(int total, boolean here, boolean sorting, boolean harvesting) {
        int previous = lastXp;
        lastXp = total;
        if (!here || previous < 0 || total <= previous) return;
        int delta = total - previous;
        if (harvesting && CargoCounter.extractorCrewForXp(delta) >= 0) {
            harvests++;
            return;
        }
        if (sorting)
            for (int crew = 0; crew <= 2; crew++)
                if (delta >= 96 + 82 * crew && delta <= 99 + 82 * crew) {
                    sorted++;
                    return;
                }
    }
}

package com.lazysalvaging;

import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

final class ShipwreckMenuSwap {
    static int select(MenuEntry[] entries) {
        if (entries.length == 0) return -1;
        MenuEntry top = entries[entries.length - 1];
        String target =
                top.getTarget() == null ? "" : top.getTarget().replaceAll("<[^>]*>", "").trim();
        if (!"Inspect".equals(top.getOption()) || !"Merchant shipwreck".equalsIgnoreCase(target))
            return -1;
        boolean worldAction = BoatMenuGuard.boatAction(top, top.getWorldViewId());
        switch (top.getType()) {
            case WORLD_ENTITY_FIRST_OPTION:
            case WORLD_ENTITY_SECOND_OPTION:
            case WORLD_ENTITY_THIRD_OPTION:
            case WORLD_ENTITY_FOURTH_OPTION:
            case WORLD_ENTITY_FIFTH_OPTION:
                worldAction = true;
                break;
            default:
                break;
        }
        if (!worldAction) return -1;
        for (int i = entries.length - 1; i >= 0; i--)
            if (entries[i].getType() == MenuAction.WALK) return i;
        return -1;
    }
}

