            expect(
                    panel.getChildren().size() == 3 && panel.getBackgroundColor().getAlpha() == 0,
                    "extractor row conditional, opacity applies to background");
            // The same controller instance is reused when the plugin is toggled off/on.
            GameState[] state = {GameState.LOGGED_IN};
            int[] xp = {1436};
            Client client =
                    (Client)
                            Proxy.newProxyInstance(
                                    Client.class.getClassLoader(),
                                    new Class<?>[] {Client.class},
                                    (proxy, method, arguments) -> {
                                        if (method.getName().equals("getGameState"))
                                            return state[0];
                                        if (method.getName().equals("getSkillExperience"))
                                            return xp[0];
                                        throw new AssertionError(
                                                "Unexpected restart API: " + method.getName());
                                    });
            set(guide, "client", client);
            guide.decision =
                    new GuideEngine.Decision(
                            GuideEngine.Action.DROP_ITEM,
                            GuideEngine.Action.USE_SEED_BOX,
                            3,
                            "Previous cleanup target");
            guide.bags.gemsKnown = true;
            set(guide, "seedDepositBlocked", true);
            guide.startSession();
            expect(
                    guide.engine.mode == GuideEngine.Mode.UNKNOWN && !guide.counter.known(),
                    "restart requires fresh phase and cargo reading");
            expect(
                    guide.decision.action == GuideEngine.Action.NONE
                            && guide.decision.preview == GuideEngine.Action.NONE
                            && guide.decision.slot == -1,
                    "restart clears stale current and preview targets immediately");
            expect(
                    !guide.bags.gemsKnown
                            && guide.totals.sorted() == 0
                            && guide.totals.harvests() == 0,
                    "restart clears capacity knowledge and totals");
            guide.totals.xp(xp[0] += 97, true, true, false);
            expect(guide.totals.sorted() == 1, "first reward after restart uses fresh baseline");
            state[0] = GameState.LOGIN_SCREEN;
            guide.startSession();
            expect(
                    guide.totals.sorted() == 0 && guide.engine.mode == GuideEngine.Mode.UNKNOWN,
                    "enabling before login also starts clean");
            expect(
                    config.seedIrit() && config.lootTiara() == LootAction.KEEP,
                    "restart preserves regular settings");
            System.out.println(
                    "Settings integration: native defaults, migration, menu-off gate, info panel"
                        + " and clean restart passed.");
        } finally {
            executor.shutdownNow();
        }
    }
}

package com.lazysalvaging;

public final class WreckAvailabilityTest {
    private static int checks;

    private static void check(boolean value, String message) {
        if (!value) throw new AssertionError(message);
        checks++;
    }

    public static void main(String[] args) {
        check(WreckAvailability.reachable(60478, 50, 50, 57, 57), "range boundary");
        check(!WreckAvailability.reachable(60478, 50, 50, 58, 50), "active but out of range");
        check(!WreckAvailability.reachable(60479, 50, 50, 50, 50), "depleted stump excluded");
        check(!WreckAvailability.reachable(60510, 50, 50, 50, 50), "hook is not a wreck");
        GuideEngine g = new GuideEngine();
        GuideEngine.View v = new GuideEngine.View();
        v.onBoat = true;
        v.cargoKnown = true;
        v.cargoSlots = 100;
        v.depleted = true;
        check(g.decide(v).action == GuideEngine.Action.NONE, "both wrecks down waits");
        check(g.decide(v).preview == GuideEngine.Action.NONE, "no hook preview while waiting");
        v.wreckAvailable = true;
        check(
                g.decide(v).action == GuideEngine.Action.DEPLOY,
                "either wreck respawning restores deploy");
        v.salvaging = true;
        check(
                g.decide(v).action == GuideEngine.Action.DEPLOY,
                "replacement wreck still overrides stale animation");
        v.depleted = false;
        check(g.decide(v).action == GuideEngine.Action.NONE, "active salvaging continues");
        v.wreckAvailable = false;
        v.occupied = 28;
        v.salvage = 20;
        check(
                g.decide(v).action == GuideEngine.Action.DEPOSIT,
                "full inventory still deposits with no wreck");
        v.occupied = 5;
        v.salvage = 0;
        v.cargoOpen = true;
        check(
                g.decide(v).action == GuideEngine.Action.CLOSE_CARGO
                        && g.decide(v).preview == GuideEngine.Action.NONE,
                "no stale close-cargo hook preview");
        v.cargoOpen = false;
        v.trackExtractor = true;
        v.extractorReady = true;
        check(
                g.decide(v).action == GuideEngine.Action.HARVEST_EXTRACTOR,
                "extractor can be tended while wrecks down");
        v.trackExtractor = false;
        g.mode = GuideEngine.Mode.SORTING;
        g.stage = GuideEngine.Stage.PROCESS;
        v.salvage = 10;
        v.salvaging = false;
        check(g.decide(v).action == GuideEngine.Action.SORT, "sorting unaffected");
        System.out.println("Wreck availability: " + checks + " checks passed.");
    }
}

package com.lazysalvaging;

public final class XpToleranceTest {
    private static int checks;

    private static void check(boolean value, String message) {
        if (!value) throw new AssertionError(message);
        checks++;
    }

    public static void main(String[] args) {
        int[][] normal = {{97, 98, 205}, {82, 179, 180, 287}, {164, 261, 262, 369}};
        for (int crew = 0; crew < 3; crew++)
            for (int base : normal[crew])
                for (int offset = -1; offset <= 1; offset++)
                    check(
                            CargoCounter.crewForXp(base + offset) == crew,
                            "normal tolerance " + base + "/" + offset);
        for (int crew = 0; crew < 3; crew++)
            for (int base : new int[] {250, 256, 257})
                for (int offset = -1; offset <= 1; offset++) {
                    int delta = base + 82 * crew + offset;
                    check(
                            CargoCounter.extractorCrewForXp(delta) == crew,
                            "extractor tolerance " + delta);
                    CargoCounter counter = new CargoCounter();
                    counter.reset(1000);
                    counter.observe(100);
                    counter.xp(1000 + delta, true, true);
                    check(
                            counter.known() && counter.slots() == 100 + crew,
                            "only crew changes cargo " + delta);
                }
        for (int delta = 1; delta < 600; delta++) {
            int normalCrew = CargoCounter.crewForXp(delta),
                    extractorCrew = CargoCounter.extractorCrewForXp(delta);
            check(
                    normalCrew < 0 || extractorCrew < 0,
                    "normal and extractor ranges do not overlap at " + delta);
        }
        for (int delta :
                new int[] {
                    80, 84, 95, 100, 166, 203, 207, 248, 252, 254, 259, 264, 285, 289, 367, 371
                })
            check(
                    CargoCounter.crewForXp(delta) < 0 && CargoCounter.extractorCrewForXp(delta) < 0,
                    "outside ranges remains unknown " + delta);
        CargoCounter counter = new CargoCounter();
        counter.reset(1000);
        counter.observe(100);
        counter.xp(1257, true, false);
        check(!counter.known(), "257 still requires harvest evidence");
        counter.reset(1000);
        counter.observe(100);
        counter.xp(1257, true, true);
        check(
                counter.known() && counter.slots() == 100,
                "screenshot 257 with harvest evidence preserves count");
        counter.xp(1257, true, true);
        check(counter.slots() == 100, "duplicate event not counted");
        System.out.println("XP tolerance: " + checks + " checks passed.");
    }
}
